def read_age(text):
    try:
        return int(text)
    except ValueError:
        return 0
    finally:
        print('Функция отработала')

print(read_age('20'))
# Функция отработала
# 20

print(read_age('ой'))
# Функция отработала
# 0

def set_age(age):
    if age < 0:
        raise ValueError('Возраст не может быть отрицательным')
    print('Возраст принят:', age)

set_age(20)     # Возраст принят: 20
set_age(-5)     # ValueError: Возраст не может быть отрицательным

