while True:
    text = input('Введите целое число: ')
    try:
        number = int(text)
        break                     # получилось — выходим из цикла
    except ValueError:
        print('Это не целое число, попробуйте снова')

print('Спасибо! Ваше число:', number)

while True:
    try:
        age = int(input('Возраст: '))
    except ValueError:
        print('Нужно число')
        continue              # обратно к вводу

    if 0 <= age <= 120:
        break                 # всё хорошо
    print('Возраст должен быть от 0 до 120')

print('Принято:', age)
